/**
 * registerSW.ts — registers the service worker (generated by vite-plugin-pwa, vite.config.ts) and
 * applies app updates at a SAFE moment.
 *
 * The service worker caches the whole app so it opens offline. We use the plugin's "prompt" mode:
 * when a new version has downloaded, the old one keeps running until WE tell the new one to take
 * over (which reloads the page). We do that automatically — no prompt for the user — but only when
 * it can't destroy work in progress:
 *   - immediately if the app is in the background (user isn't looking), or
 *   - when the user is on a bottom-nav tab (Inicio, Temas, Exámenes, Perfil, Ajustes),
 *   - never in the middle of an exam, a study question, or while typing an unlock code.
 * Open apps also check for updates every hour. Docs: docs/DEPLOY.md → "How updates reach phones".
 */
import { registerSW } from 'virtual:pwa-register'
import { TAB_ROUTES } from '../ui/router'

let pendingUpdate: ((reload?: boolean) => Promise<void>) | null = null

function safeToReload(): boolean {
  if (document.visibilityState === 'hidden') return true
  const path = window.location.hash.replace(/^#/, '') || '/home'
  return (TAB_ROUTES as readonly string[]).includes(path)
}

function applyIfSafe(): void {
  if (pendingUpdate && safeToReload()) {
    const apply = pendingUpdate
    pendingUpdate = null
    void apply(true)
  }
}

/** Registers the service worker (no-op in dev and in browsers without support). */
export function registerServiceWorker(): void {
  if (!('serviceWorker' in navigator) || import.meta.env.DEV) return
  const updateSW = registerSW({
    immediate: true,
    onNeedRefresh() {
      pendingUpdate = updateSW
      applyIfSafe()
    },
    onRegisteredSW(_url, registration) {
      if (!registration) return
      setInterval(() => void registration.update(), 60 * 60 * 1000)
    },
  })
  window.addEventListener('hashchange', applyIfSafe)
  document.addEventListener('visibilitychange', applyIfSafe)
}
